func (c *Component) startHeartbeat(ctx context.Context) context.CancelFunc {
	interval := parseDurationOrDefault(c.config.HeartbeatInterval, 30*time.Second)
	hbCtx, cancel := context.WithCancel(ctx)

	go func() {
		ticker := time.NewTicker(interval)
		defer ticker.Stop()

		for {
			select {
			case <-hbCtx.Done():
				return
			case <-ticker.C:
				c.statusMu.RLock()
				status := c.aggregator.buildStatus(c.config.Namespace)
				c.statusMu.RUnlock()
				c.updateStatusData(status)

				if err := c.publishPayload(hbCtx, StatusType, status, statusSubject); err != nil {
					// The heartbeat IS the liveness signal; losing it silently
					// makes a live instance look dead. Edge-triggered (ADR-0011).
					c.heartbeatFailing.Enter(c.logger,
						"heartbeat publishing is failing — liveness will look stale", "error", err)
				} else {
					c.heartbeatFailing.Clear(c.logger, "heartbeat publishing recovered")
				}
			}
		}
	}()

	return cancel
}

func (c *Component) configuredSourceTypes() []string {
	seen := make(map[string]bool)
	var types []string
	for _, src := range c.config.Sources {
		if !seen[src.Type] {
			seen[src.Type] = true
			types = append(types, src.Type)
		}
	}
	return types
}

