func (c *Component) removeSource(ctx context.Context, instanceName, actor string, cfg IngestHandlerConfig) *RemoveReply {
	// Captured BEFORE the KV delete below removes the component config —
	// systemsForRemovedInstance reads it back to scope the lifecycle trigger.
	systems := systemsForRemovedInstance(instanceName, cfg.Store)

	if err := sourcespawn.Remove(ctx, instanceName, cfg.Store); err != nil {
		return &RemoveReply{
			InstanceName: instanceName,
			Error:        mapSpawnError(err),
			Timestamp:    time.Now(),
		}
	}

	c.logger.Info("source removed via ingest API",
		"namespace", cfg.Namespace,
		"instance_name", instanceName,
		"actor", actor)

	// Drop the removed source from status aggregation immediately — before
	// this, removed sources reported as phantom "watching" entries forever
	// (audit 2026-07-19, live-confirmed at a 20-minute horizon).
	c.dropSourceStatus(ctx, instanceName)

	if c.removeManifestSourceByInstance(instanceName, cfg.Spawn, cfg.Store) {
		if err := c.publishManifest(ctx); err != nil {
			c.logger.Warn("failed to republish manifest after remove", "error", err)
		}
	}

	// Async, best-effort: retro-mark the removed source's retained entities.
	// No root_path — the source itself is gone, so every in-scope entity is
	// unconditionally marked, not just entities whose file happens to be
	// missing (design D4). A resolution miss (unrecognized factory type, no
	// client) degrades staleness marking; it never fails the removal itself.
	if len(systems) > 0 {
		c.triggerRemovalLifecycleRun(ctx, cfg.Spawn.Org, systems)
	}

	return &RemoveReply{
		InstanceName: instanceName,
		Removed:      true,
		Timestamp:    time.Now(),
	}
}

func parseDurationOrDefault(s string, def time.Duration) time.Duration {
	if s == "" {
		return def
	}
	d, err := time.ParseDuration(s)
	if err != nil {
		return def
	}
	return d
}

func (c *Component) handleHealth(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	c.mu.RLock()
	running := c.running
	c.mu.RUnlock()

	payload := c.buildHealthPayload(running)
	w.Header().Set("Content-Type", "application/json")
	if !payload.Healthy && !running {
		w.WriteHeader(http.StatusServiceUnavailable)
	}
	_ = json.NewEncoder(w).Encode(payload)
}

func (c *Component) startSeedTimeout(ctx context.Context) context.CancelFunc {
	timeout := parseDurationOrDefault(c.config.SeedTimeout, 120*time.Second)
	if c.config.ExpectedSourceCount <= 0 {
		return nil
	}

	toCtx, cancel := context.WithCancel(ctx)

	go func() {
		timer := time.NewTimer(timeout)
		defer timer.Stop()

		select {
		case <-toCtx.Done():
			return
		case <-timer.C:
			c.statusMu.Lock()
			if c.seedComplete {
				c.statusMu.Unlock()
				return
			}
			// Do NOT set seedComplete here — the timer is one-shot so there's
			// nothing to guard against re-firing, and marking seed complete
			// prevents the recovery publish in handleStatusReport from firing
			// when a late source finally reports.
			status := c.aggregator.markDegraded(c.config.Namespace)
			c.statusMu.Unlock()

			c.updateStatusData(status)
			c.logger.Warn("seed timeout — marking status degraded (may recover)",
				"expected", c.config.ExpectedSourceCount,
				"received", len(status.Sources))

			if err := c.publishPayload(toCtx, StatusType, status, statusSubject); err != nil {
				c.logger.Warn("failed to publish degraded status", "error", err)
			}
		}
	}()

	return cancel
}

