func (c *Component) handleStatusReport(ctx context.Context, data []byte) {
	var report SourceStatusReport
	if err := json.Unmarshal(data, &report); err != nil {
		c.logger.Warn("invalid status report", "error", err)
		return
	}

	c.statusMu.Lock()
	if _, removed := c.removedSources[report.InstanceName]; removed {
		// A deregistered component's last in-flight report must not
		// resurrect its status entry (source-removal-integrity).
		c.statusMu.Unlock()
		return
	}
	wasComplete := c.seedComplete
	wasDegraded := c.aggregator.degraded
	c.aggregator.update(&report)
	// Seed-complete means SEEDED (every source watching/idle), not merely
	// all-reported — components report "ingesting" at Start, and treating
	// first-reports as completion was exactly the mid-seed ready gate the
	// audit flagged (honest-readiness-and-errors). This also keeps the
	// seed-timeout live until sources actually finish seeding.
	nowComplete := c.aggregator.allSeeded() && !c.aggregator.anyErrored()
	if nowComplete {
		c.seedComplete = true
		// Clear the sticky degraded flag — a late source finally reporting
		// means we recovered. The aggregator already returns PhaseReady in
		// this case, but leaving degraded=true on the record would confuse
		// any future buildStatus call that happened when reports drop below
		// expectedCount again.
		c.aggregator.degraded = false
	}
	status := c.aggregator.buildStatus(c.config.Namespace)
	c.statusMu.Unlock()

	c.updateStatusData(status)

	// Publish the phase transition to consumers. Recovery (degraded → ready)
	// must be checked first because wasComplete is also false in that case
	// (we intentionally don't set seedComplete on the degraded timeout).
	switch {
	case nowComplete && wasDegraded:
		c.logger.Info("late source reported — recovered from degraded",
			"total_entities", status.TotalEntities,
			"sources", len(status.Sources))
		if err := c.publishPayload(ctx, StatusType, status, statusSubject); err != nil {
			c.logger.Warn("failed to publish recovery status", "error", err)
		}
	case nowComplete && !wasComplete:
		c.logger.Info("all sources seeded — seed complete",
			"total_entities", status.TotalEntities,
			"sources", len(status.Sources))
		if err := c.publishPayload(ctx, StatusType, status, statusSubject); err != nil {
			c.logger.Warn("failed to publish seed-complete status", "error", err)
		}
	}
}

func (c *Component) Stop(_ time.Duration) error {
	c.mu.Lock()
	defer c.mu.Unlock()

	if !c.running {
		return nil
	}

	for _, cancel := range c.cancelFuncs {
		cancel()
	}
	c.cancelFuncs = nil

	subs := []*natsclient.Subscription{c.querySub, c.statusSub, c.statusQuerySub, c.predicatesQuerySub, c.summaryQuerySub}
	subs = append(subs, c.ingestSubs...)
	for _, sub := range subs {
		if sub != nil {
			if err := sub.Unsubscribe(); err != nil {
				c.logger.Warn("failed to unsubscribe", "error", err)
			}
		}
	}
	c.querySub = nil
	c.statusSub = nil
	c.statusQuerySub = nil
	c.predicatesQuerySub = nil
	c.summaryQuerySub = nil
	c.ingestSubs = nil

	c.running = false
	c.logger.Info("source-manifest stopped")
	return nil
}

