func (c *Component) handleRemoveRequest(ctx context.Context, data []byte, cfg IngestHandlerConfig) ([]byte, error) {
	var req RemoveRequest
	if err := json.Unmarshal(data, &req); err != nil {
		return marshalRemoveReply(&RemoveReply{
			Error: &IngestError{
				Code:    CodeValidationFailed,
				Message: fmt.Sprintf("decode request: %v", err),
			},
			Timestamp: time.Now(),
		})
	}
	return marshalRemoveReply(c.removeSource(ctx, req.InstanceName, req.Provenance.Actor, cfg))
}

func (c *Component) handleAddHTTP(w http.ResponseWriter, r *http.Request) {
	cfg, ok := c.authorizedIngest(w, r)
	if !ok {
		return
	}

	var req AddRequest
	dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, maxAddBodyBytes))
	if err := dec.Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, &AddReply{
			Error:     &IngestError{Code: CodeValidationFailed, Message: "decode request: " + err.Error()},
			Timestamp: time.Now(),
		})
		return
	}

	// Path allowlist (ADR-0007 §3): a path-based source over HTTP must resolve
	// under an allowlisted root; arbitrary host paths are rejected.
	if err := sourceallow.Enforce(req.Source, cfg.AllowedRoots); err != nil {
		writeJSON(w, http.StatusForbidden, &AddReply{
			Error:     &IngestError{Code: CodeValidationFailed, Message: err.Error()},
			Timestamp: time.Now(),
		})
		return
	}

	reply := c.addSource(r.Context(), req, *cfg)
	status := http.StatusOK
	if reply.Error != nil && len(reply.Components) == 0 {
		status = httpStatusForIngestError(reply.Error.Code)
	}
	writeJSON(w, status, reply)
}

type Component struct {
	name   string
	config Config
	// heartbeatFailing: the heartbeat is the liveness signal, so its loss must
	// be visible without logging once per interval (ADR-0011).
	heartbeatFailing degraded.Condition
	client           *natsclient.Client
	logger           *slog.Logger
	// readinessRequest is a test seam for the two bounded index-status probes
	// used by the workbench capability document. Production leaves it nil and
	// reads GRAPH_STATUS through graphStatus instead.
	readinessRequest readinessRequestFunc
	readinessTimeout time.Duration
	// graphStatus reads ADR-083 readiness envelopes from the GRAPH_STATUS KV
	// bucket. It replaces the removed graph.index.query.status request/reply.
	graphStatus *graphstatus.Reader

	// Manifest query
	querySub     *natsclient.Subscription
	responseData []byte // pre-marshaled manifest for HTTP and NATS responses
	// manifestMu guards responseData and the underlying sources slice
	// (config.Sources is stable post-Start, but the canonical "what's
	// configured" list is mutated by ingest Add/Remove).
	manifestMu      sync.RWMutex
	manifestSources []ManifestSource

	// Status aggregation
	aggregator     *statusAggregator
	statusSub      *natsclient.Subscription
	statusQuerySub *natsclient.Subscription
	statusData     []byte // pre-marshaled latest status for HTTP and NATS
	statusMu       sync.RWMutex
	seedComplete   bool
	// removedSources guards against in-flight periodic reports from
	// deregistered components resurrecting phantom status entries. Cleared
	// per-instance on re-add. Guarded by statusMu.
	removedSources map[string]struct{}

	// Predicate schema
	predicatesQuerySub *natsclient.Subscription
	predicatesData     []byte // pre-marshaled predicate schema for HTTP and NATS

	// Summary query
	summaryQuerySub *natsclient.Subscription

	// Ingest API (graph.ingest.add/remove + HTTP POST/DELETE/GET /sources).
	// ingestCfg is nil until RegisterIngestHandlers runs (host wires it after
	// Start); the HTTP façade handlers read it at request time and 503 while nil.
	// Guarded by c.mu.
	ingestSubs []*natsclient.Subscription
	ingestCfg  *IngestHandlerConfig

	// Background goroutine cancellation
	cancelFuncs []context.CancelFunc

	running   bool
	startTime time.Time
	mu        sync.RWMutex
}

func (c *Component) authorizedIngest(w http.ResponseWriter, r *http.Request) (*IngestHandlerConfig, bool) {
	if !c.requireRunning(w) {
		return nil, false
	}
	cfg := c.ingestConfig()
	if cfg == nil {
		http.Error(w, "source registration not ready", http.StatusServiceUnavailable)
		return nil, false
	}
	if !authorized(r, cfg.APIToken) {
		w.Header().Set("WWW-Authenticate", "Bearer")
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return nil, false
	}
	return cfg, true
}

func (c *Component) Health() component.HealthStatus {
	c.mu.RLock()
	running := c.running
	startTime := c.startTime
	c.mu.RUnlock()

	status := "stopped"
	if running {
		status = "running"
	}

	return component.HealthStatus{
		Healthy:   running,
		LastCheck: time.Now(),
		Uptime:    time.Since(startTime),
		Status:    status,
	}
}

