func (c *Component) removeManifestSourceByInstance(instanceName string, opts sourcespawn.Options, store sourcespawn.ConfigStore) bool {
	c.manifestMu.Lock()
	defer c.manifestMu.Unlock()
	for i, existing := range c.manifestSources {
		built, err := sourcespawn.Build(manifestSourceToSourceEntry(existing), opts)
		if err != nil {
			continue
		}
		if _, ok := built[instanceName]; !ok {
			continue
		}
		// This entry owns the removed instance. Keep the entry while any
		// sibling instance of the same expansion remains registered.
		if store != nil {
			if cfg := store.GetConfig().Get(); cfg != nil {
				for sibling := range built {
					if sibling == instanceName {
						continue
					}
					if _, alive := cfg.Components[sibling]; alive {
						return false
					}
				}
			}
		}
		c.manifestSources = append(c.manifestSources[:i], c.manifestSources[i+1:]...)
		return true
	}
	return false
}

func httpStatusForIngestError(code IngestErrorCode) int {
	switch code {
	case CodeValidationFailed, CodeUnsupportedType:
		return http.StatusBadRequest
	case CodeInstanceExists:
		return http.StatusConflict
	case CodeNotFound:
		return http.StatusNotFound
	default:
		return http.StatusInternalServerError
	}
}

func (a *statusAggregator) allSeeded() bool {
	if !a.allReported() {
		return false
	}
	for _, r := range a.reports {
		if r.Phase != SourcePhaseWatching && r.Phase != SourcePhaseIdle {
			return false
		}
	}
	return true
}

func (c *Component) handleStatus(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	if !c.requireRunning(w) {
		return
	}
	c.statusMu.RLock()
	data := c.statusData
	c.statusMu.RUnlock()

	// Readiness parity with the MCP source_status tool (audit 2026-07-19): the
	// README documents polling this endpoint for index.ready / embedding.ready,
	// but those fields never existed here. Additive top-level fields keep the
	// envelope backward compatible (namespace/phase/sources untouched); failed
	// sub-queries yield explicit {available:false, reason}, never key omission.
	var payload map[string]any
	if err := json.Unmarshal(data, &payload); err == nil {
		ctx := r.Context()
		payload["index"] = c.fetchIndexReadiness(ctx, structuralReadinessKey, "structural index")
		payload["embedding"] = c.fetchIndexReadiness(ctx, semanticReadinessKey, "semantic index")
		payload["note"] = ReadinessNote
		if merged, mErr := json.Marshal(payload); mErr == nil {
			data = merged
		}
	}

	w.Header().Set("Content-Type", "application/json")
	w.Write(data)
}

func (c *Component) handleRemoveHTTP(w http.ResponseWriter, r *http.Request) {
	cfg, ok := c.authorizedIngest(w, r)
	if !ok {
		return
	}
	id := r.PathValue("id")
	if id == "" {
		http.Error(w, "missing source id", http.StatusBadRequest)
		return
	}
	reply := c.removeSource(r.Context(), id, r.Header.Get("X-Actor"), *cfg)
	status := http.StatusOK
	if reply.Error != nil {
		status = httpStatusForIngestError(reply.Error.Code)
	}
	writeJSON(w, status, reply)
}

func mapSpawnError(err error) *IngestError {
	var serr *sourcespawn.Error
	if !errors.As(err, &serr) {
		return &IngestError{Code: CodeInternalError, Message: err.Error()}
	}
	code := CodeValidationFailed
	switch serr.Code {
	case sourcespawn.CodeValidationFailed:
		code = CodeValidationFailed
	case sourcespawn.CodeInstanceExists:
		code = CodeInstanceExists
	case sourcespawn.CodeKVWriteFailed:
		code = CodeKVWriteFailed
	case sourcespawn.CodeUnsupportedType:
		code = CodeUnsupportedType
	case sourcespawn.CodeNotFound:
		code = CodeNotFound
	}
	return &IngestError{Code: code, Message: serr.Message}
}

func authorized(r *http.Request, token string) bool {
	if token == "" {
		return true
	}
	h := r.Header.Get("Authorization")
	if !strings.HasPrefix(h, "Bearer ") {
		return false
	}
	got := strings.TrimPrefix(h, "Bearer ")
	return subtle.ConstantTimeCompare([]byte(got), []byte(token)) == 1
}

func (c *Component) dropSourceStatus(ctx context.Context, instanceName string) {
	c.statusMu.Lock()
	if c.removedSources == nil {
		c.removedSources = make(map[string]struct{})
	}
	c.removedSources[instanceName] = struct{}{}
	if c.aggregator == nil || !c.aggregator.remove(instanceName) {
		c.statusMu.Unlock()
		return
	}
	status := c.aggregator.buildStatus(c.config.Namespace)
	c.statusMu.Unlock()

	c.updateStatusData(status)
	if err := c.publishPayload(ctx, StatusType, status, statusSubject); err != nil {
		c.logger.Warn("failed to publish status after source removal", "error", err)
	}
}

