func patternRole(name string) string {
	parts := strings.Split(name, ".")
	if len(parts) < 3 {
		return RoleMetadata
	}

	category := parts[len(parts)-2]
	switch category {
	case "relationship", "structure", "dependency":
		return RoleRelationship
	case "metric":
		return RoleMetric
	}

	// Check by second segment (domain.category.property pattern)
	if len(parts) >= 3 {
		switch parts[1] {
		case "relationship", "structure", "dependency":
			return RoleRelationship
		case "metric":
			return RoleMetric
		}
	}

	return RoleMetadata
}

func manifestSourcesEqual(a, b ManifestSource) bool {
	if a.Type != b.Type || a.Path != b.Path || a.URL != b.URL || a.Branch != b.Branch {
		return false
	}
	if !stringSliceEqual(a.Paths, b.Paths) || !stringSliceEqual(a.URLs, b.URLs) {
		return false
	}
	return true
}

